def side(m, k):
    if m == 0:
        return f"{k}"
    if m == 1:
        term = "x"
    elif m == -1:
        term = "-x"
    else:
        term = f"{m}x"
    if k > 0:
        return f"{term} + {k}"
    if k < 0:
        return f"{term} - {-k}"
    return term


from fractions import Fraction
from sympy import symbols, Eq, solve
x = symbols("x")


def check(a, b, c, d, candidates):
    print(f"{side(a, b)} = {side(c, d)}")
    for v in candidates:
        left = a * v + b
        right = c * v + d
        print(f"  x = {v}: left {left}, right {right}, solution: {left == right}")
    print(f"  sympy: {solve(Eq(a*x + b, c*x + d), x)}")


check(3, 5, 0, 20, [4, 5])
check(2, -7, -1, 8, [5])
check(4, 11, 0, 3, [-2, 2])
check(2, 1, 0, 4, [1, 2, Fraction(3, 2)])

