from fractions import Fraction


def solve_steps(a, b, c, d):
    print(f"{side(a, b)} = {side(c, d)}")
    print(f"  subtract {c}x from both sides: {side(a - c, b)} = {d}")
    print(f"  subtract {b} from both sides: {side(a - c, 0)} = {d - b}")
    x = Fraction(d - b, a - c)
    print(f"  divide both sides by {a - c}: x = {x}")
    print(f"  check: left {a * x + b}, right {c * x + d}")


solve_steps(3, 5, 0, 20)
solve_steps(-2, 7, 0, 1)
solve_steps(5, -4, 2, 11)
solve_steps(4, 7, 0, 1)

