from fractions import Fraction
from sympy import symbols, Eq, solve
x = symbols("x")


def classify(a, b, c, d):
    print(f"{side(a, b)} = {side(c, d)}")
    coef, right = a - c, d - b
    print(f"  subtract {c}x and {b}: {coef}x = {right}")
    if coef != 0:
        print(f"  one solution: x = {Fraction(right, coef)}")
    elif right == 0:
        print("  0 = 0 for every x: an identity, every number is a solution")
    else:
        print(f"  0 = {right} for every x: a contradiction, no solution")
    print(f"  sympy: Eq gives {Eq(a*x + b, c*x + d)}, solve gives {solve(Eq(a*x + b, c*x + d), x)}")


classify(2, 3, 5, -9)
classify(2, 6, 2, 6)
classify(2, 6, 2, 5)
classify(7, 2, 0, 2)
classify(2, 10, 3, 4)

