from fractions import Fraction

count = int(input())
for i in range(count):
    p = int(input())
    q = int(input())
    r = int(input())
    s = int(input())
    const = p * q
    coef = p - r
    right = s - const
    print(f"Problem {i + 1}: {p}({side(1, q)}) = {side(r, s)}")
    print(f"  distribute: {side(p, const)} = {side(r, s)}")
    print(f"  reduce: {coef}x = {right}")
    if coef != 0:
        print(f"  one solution: x = {Fraction(right, coef)}")
    elif right == 0:
        print("  identity: every number is a solution")
    else:
        print("  contradiction: no solution")
